#!/usr/bin/env bash
# Parse the tracked configuration files. config/game.toml is generated by xbe_symbols and is
# not tracked, so only the hand-authored files can be checked on a fresh clone.
set -euo pipefail

cd "$(git rev-parse --show-toplevel)"

python3 - <<'PY'
import json
import tomllib

with open("config/outrun2.toml", "rb") as handle:
    config = tomllib.load(handle)
tables = ", ".join(sorted(config))
print(f"config/outrun2.toml: ok ({len(config)} top-level table(s): {tables})")

with open("CMakePresets.json", "r", encoding="utf-8") as handle:
    presets = json.load(handle)
configure = presets.get("configurePresets", [])
build = presets.get("buildPresets", [])
print(f"CMakePresets.json: ok (version {presets.get('version')}, {len(configure)} configure preset(s), {len(build)} build preset(s))")
PY

if [ -f config/game.toml ]; then
    python3 - <<'PY'
import tomllib
with open("config/game.toml", "rb") as handle:
    game = tomllib.load(handle)
print(f"config/game.toml: ok ({len(game)} top-level table(s))")
PY
else
    echo "config/game.toml: not present (generated by xbe_symbols; expected on a fresh clone)"
fi

echo "config: passed"
